///
/// Replays the cross-platform wire-format vectors in `bitchat-ios.json`
/// against the BitFoundation codec and asserts byte-exact equality.
///
/// The vectors were generated by this very codec (see the `source` /
/// `generator` fields in the file) and are shared with the Android client and
/// with third-party implementations, so a failure here means the wire format
/// moved: either the change is intentional (regenerate and ship new vectors to
/// every platform) or it is a regression.
///
/// Vector file resolution, in order:
/// 1. `SONAR_VECTOR_FILE` environment variable (absolute path).
/// 2. A `bitchat-ios.json` file next to this source file.
/// If neither exists the whole suite is disabled with a message, not failed.
///
/// Hex encoding in the file: every byte field is a lowercase hex string. A
/// run of one byte repeated 1024 times or more is written as `repeat:xx*N`
/// (`xx` = the byte in hex, `N` = count in decimal), e.g. `repeat:00*65535`.
///
/// Kinds whose types live in the app target (announce_tlv, announce_decode,
/// peer_state_tlv, private_message_tlv, noise_payload, file_packet_tlv,
/// fragment_payload) are counted and skipped here; `BitchatAppVectorReplayTests`
/// in `bitchatTests/` replays them with the real app types.
///

import Foundation
import Testing
@testable import BitFoundation

// MARK: - Vector file model

/// Minimal JSON value that keeps 64-bit integers exact (capabilities use the
/// full `UInt64` range, which `Double` cannot represent).
private indirect enum JV: Decodable {
    case null
    case bool(Bool)
    case uint(UInt64)
    case int(Int64)
    case double(Double)
    case string(String)
    case array([JV])
    case object([String: JV])

    init(from decoder: any Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .null; return }
        if let v = try? c.decode(Bool.self) { self = .bool(v); return }
        if let v = try? c.decode(UInt64.self) { self = .uint(v); return }
        if let v = try? c.decode(Int64.self) { self = .int(v); return }
        if let v = try? c.decode(Double.self) { self = .double(v); return }
        if let v = try? c.decode(String.self) { self = .string(v); return }
        if let v = try? c.decode([JV].self) { self = .array(v); return }
        self = .object(try c.decode([String: JV].self))
    }

    subscript(_ key: String) -> JV {
        if case .object(let o) = self, let v = o[key] { return v }
        return .null
    }
    var isNull: Bool { if case .null = self { return true }; return false }
    var string: String? { if case .string(let s) = self { return s }; return nil }
    var bool: Bool? { if case .bool(let b) = self { return b }; return nil }
    var u64: UInt64? {
        switch self {
        case .uint(let v): return v
        case .int(let v): return v >= 0 ? UInt64(v) : nil
        case .double(let v): return v >= 0 ? UInt64(v) : nil
        default: return nil
        }
    }
    var int: Int? { u64.flatMap { Int(exactly: $0) } }
    var array: [JV]? { if case .array(let a) = self { return a }; return nil }
    /// Hex field, expanding the `repeat:xx*N` run-length form. `nil` for JSON null.
    var hex: Data? {
        guard let s = string else { return nil }
        return expandHex(s)
    }
    var hexList: [Data]? { array?.compactMap { $0.hex } }
}

private func expandHex(_ s: String) -> Data? {
    if s.hasPrefix("repeat:") {
        let body = s.dropFirst("repeat:".count)
        let parts = body.split(separator: "*", maxSplits: 1)
        guard parts.count == 2, let byte = UInt8(parts[0], radix: 16), let count = Int(parts[1]) else { return nil }
        return Data(repeating: byte, count: count)
    }
    if s.isEmpty { return Data() }
    return Data(hexString: s)
}

private struct VectorCase {
    let name: String
    let kind: String
    let input: JV
    let expected: JV
}

private struct VectorFile {
    let path: String
    let source: String
    let cases: [VectorCase]

    static let resolvedPath: String? = {
        let env = ProcessInfo.processInfo.environment["SONAR_VECTOR_FILE"]
        if let env, !env.isEmpty, FileManager.default.fileExists(atPath: env) { return env }
        let sibling = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent("bitchat-ios.json").path
        if FileManager.default.fileExists(atPath: sibling) { return sibling }
        return nil
    }()

    static var isAvailable: Bool { resolvedPath != nil }

    static let shared: VectorFile? = {
        guard let path = resolvedPath, let data = FileManager.default.contents(atPath: path) else { return nil }
        guard let root = try? JSONDecoder().decode(JV.self, from: data), let list = root["cases"].array else { return nil }
        let cases = list.map {
            VectorCase(name: $0["name"].string ?? "?", kind: $0["kind"].string ?? "?", input: $0["input"], expected: $0["expected"])
        }
        return VectorFile(path: path, source: root["source"].string ?? "?", cases: cases)
    }()

    static func cases(_ kind: String) throws -> [VectorCase] {
        let file = try #require(shared, "vector file could not be parsed")
        let list = file.cases.filter { $0.kind == kind }
        print("REPLAY kind=\(kind) cases=\(list.count) file=\(file.path)")
        return list
    }
}

/// Kinds replayed by this suite.
private let bitFoundationKinds: Set<String> = [
    "padding", "optimal_block_size", "unpad", "should_compress", "compress",
    "packet_encode", "packet_decode_reject", "packet_decode_accept", "peer_id", "capabilities"
]
/// Kinds whose codecs live in the app target; replayed by `BitchatAppVectorReplayTests`.
private let appTargetKinds: Set<String> = [
    "announce_tlv", "announce_decode", "peer_state_tlv", "private_message_tlv",
    "noise_payload", "file_packet_tlv", "fragment_payload"
]

private func makePacket(_ i: JV) throws -> BitchatPacket {
    BitchatPacket(
        type: UInt8(try #require(i["type"].int)),
        senderID: try #require(i["sender_id"].hex),
        recipientID: i["recipient_id"].hex,
        timestamp: try #require(i["timestamp"].u64),
        payload: try #require(i["payload"].hex),
        signature: i["signature"].hex,
        ttl: UInt8(try #require(i["ttl"].int)),
        version: UInt8(try #require(i["version"].int)),
        route: i["route"].hexList,
        isRSR: i["is_rsr"].bool ?? false
    )
}

// MARK: - Suite

@Suite("bitchat-ios.json vector replay (BitFoundation)",
       .enabled(if: VectorFile.isAvailable,
                "No vector file: set SONAR_VECTOR_FILE=/path/to/bitchat-ios.json or place bitchat-ios.json next to BitchatVectorReplayTests.swift"))
struct BitchatVectorReplayTests {

    @Test func everyKindInTheFileIsReplayedSomewhere() throws {
        let file = try #require(VectorFile.shared)
        var counts: [String: Int] = [:]
        for c in file.cases { counts[c.kind, default: 0] += 1 }
        let unknown = Set(counts.keys).subtracting(bitFoundationKinds).subtracting(appTargetKinds)
        #expect(unknown.isEmpty, "vector kinds with no replay: \(unknown.sorted())")
        let skipped = counts.filter { appTargetKinds.contains($0.key) }
        let skippedTotal = skipped.values.reduce(0, +)
        print("REPLAY skipped app-target kinds here (see BitchatAppVectorReplayTests): \(skippedTotal) cases in \(skipped.keys.sorted())")
        print("REPLAY source=\(file.source) total_cases=\(file.cases.count)")
    }

    @Test func padding() throws {
        for c in try VectorFile.cases("padding") {
            let data = try #require(c.input["data"].hex, "\(c.name)")
            let target = try #require(c.input["target"].int, "\(c.name)")
            #expect(MessagePadding.pad(data, toSize: target) == c.expected["padded"].hex, "\(c.name)")
        }
    }

    @Test func optimalBlockSize() throws {
        for c in try VectorFile.cases("optimal_block_size") {
            let size = try #require(c.input["size"].int, "\(c.name)")
            #expect(MessagePadding.optimalBlockSize(for: size) == c.expected["block"].int, "\(c.name)")
        }
    }

    @Test func unpad() throws {
        for c in try VectorFile.cases("unpad") {
            let data = try #require(c.input["data"].hex, "\(c.name)")
            #expect(MessagePadding.unpad(data) == c.expected["unpadded"].hex, "\(c.name)")
        }
    }

    @Test func shouldCompress() throws {
        for c in try VectorFile.cases("should_compress") {
            let payload = try #require(c.input["payload"].hex, "\(c.name)")
            #expect(CompressionUtil.shouldCompress(payload) == c.expected["result"].bool, "\(c.name)")
        }
    }

    /// Byte-exact: the vectors are the output of Apple's `COMPRESSION_ZLIB`
    /// (raw DEFLATE) encoder via `CompressionUtil.compress`, which has been
    /// stable across macOS/iOS releases. If a future libcompression changes
    /// its DEFLATE output, relax the first `#expect` to the inflate round-trip
    /// below (which is the actual interop contract: peers must be able to
    /// inflate what we send, not reproduce it) and regenerate the vectors.
    @Test func compress() throws {
        for c in try VectorFile.cases("compress") {
            let payload = try #require(c.input["payload"].hex, "\(c.name)")
            let expected = c.expected["compressed"].hex
            let actual = CompressionUtil.compress(payload)
            #expect(actual == expected, "\(c.name): compressed bytes differ")
            if let expected {
                #expect(CompressionUtil.decompress(expected, originalSize: payload.count) == payload, "\(c.name): inflate round-trip")
            }
        }
    }

    @Test func packetEncode() throws {
        for c in try VectorFile.cases("packet_encode") {
            let packet = try makePacket(c.input)
            if let should = c.input["should_compress"].bool {
                #expect(CompressionUtil.shouldCompress(packet.payload) == should, "\(c.name): should_compress")
            }
            let padded = BinaryProtocol.encode(packet, padding: true)
            let unpadded = BinaryProtocol.encode(packet, padding: false)
            #expect(padded == c.expected["padded"].hex, "\(c.name): padded")
            #expect(unpadded == c.expected["unpadded"].hex, "\(c.name): unpadded")
            guard let padded, let unpadded, !c.expected["padded"].isNull else { continue }

            if !c.expected["signing_preimage"].isNull {
                #expect(packet.toBinaryDataForSigning() == c.expected["signing_preimage"].hex, "\(c.name): signing preimage")
            }
            if let flags = c.expected["decoded_flags"].int {
                #expect(Int(unpadded[BinaryProtocol.Offsets.flags]) == flags, "\(c.name): flags byte")
            }
            let decoded = try #require(BinaryProtocol.decode(padded), "\(c.name): padded frame must decode")
            #expect(decoded.payload == c.expected["decoded_payload"].hex, "\(c.name): decoded payload")
            #expect(decoded.payload == packet.payload, "\(c.name): payload round-trip")
            if !c.expected["decoded_ttl"].isNull { #expect(Int(decoded.ttl) == c.expected["decoded_ttl"].int, "\(c.name): ttl") }
            if let rsr = c.expected["decoded_is_rsr"].bool { #expect(decoded.isRSR == rsr, "\(c.name): isRSR") }
            if case .object(let o) = c.expected {
                if o["decoded_recipient_id"] != nil { #expect(decoded.recipientID == c.expected["decoded_recipient_id"].hex, "\(c.name): recipient") }
                if o["decoded_sender_id"] != nil { #expect(decoded.senderID == c.expected["decoded_sender_id"].hex, "\(c.name): sender") }
                if o["decoded_signature"] != nil { #expect(decoded.signature == c.expected["decoded_signature"].hex, "\(c.name): signature") }
                if o["decoded_route"] != nil { #expect(decoded.route == c.expected["decoded_route"].hexList, "\(c.name): route") }
            }
            let fromUnpadded = try #require(BinaryProtocol.decode(unpadded), "\(c.name): unpadded frame must decode")
            #expect(fromUnpadded.payload == packet.payload, "\(c.name): unpadded payload round-trip")
        }
    }

    @Test func packetDecodeReject() throws {
        for c in try VectorFile.cases("packet_decode_reject") {
            let bytes = try #require(c.input["bytes"].hex, "\(c.name)")
            #expect(c.expected["decodes"].bool == false, "\(c.name): vector must expect rejection")
            #expect(BinaryProtocol.decode(bytes) == nil, "\(c.name): must be rejected")
        }
    }

    @Test func packetDecodeAccept() throws {
        for c in try VectorFile.cases("packet_decode_accept") {
            let bytes = try #require(c.input["bytes"].hex, "\(c.name)")
            let decoded = try #require(BinaryProtocol.decode(bytes), "\(c.name): must decode")
            #expect(c.expected["decodes"].bool == true, "\(c.name)")
            #expect(decoded.payload == c.expected["payload"].hex, "\(c.name): payload")
            if case .object(let o) = c.expected, o["route"] != nil {
                #expect(decoded.route == c.expected["route"].hexList, "\(c.name): route")
            }
            if let flags = c.expected["flags"].int {
                #expect(Int(bytes[BinaryProtocol.Offsets.flags]) == flags, "\(c.name): flags byte")
            }
        }
    }

    @Test func peerID() throws {
        for c in try VectorFile.cases("peer_id") {
            let key = try #require(c.input["noise_public_key"].hex, "\(c.name)")
            let pid = PeerID(publicKey: key)
            #expect(pid.id == c.expected["peer_id"].string, "\(c.name): id")
            if let bare = c.expected["bare"].string { #expect(pid.bare == bare, "\(c.name): bare") }
            if let sha = c.expected["sha256"].string { #expect(key.sha256Fingerprint() == sha, "\(c.name): sha256") }
        }
    }

    @Test func capabilities() throws {
        for c in try VectorFile.cases("capabilities") {
            if let raw = c.input["raw"].u64 {
                #expect(PeerCapabilities(rawValue: raw).encoded() == c.expected["encoded"].hex, "\(c.name): encode")
            } else {
                let encoded = try #require(c.input["encoded"].hex, "\(c.name)")
                let caps = PeerCapabilities(encoded: encoded)
                #expect(caps.rawValue == c.expected["raw"].u64, "\(c.name): decode")
                if !c.expected["reencoded"].isNull {
                    #expect(caps.encoded() == c.expected["reencoded"].hex, "\(c.name): re-encode")
                }
            }
        }
    }
}
